"""Board plugin for running CAVE RESCUE under multi-agent-harness.

The whole team shares one rescue simulation, which runs root-only on the hub. Agents reach it through the hub gateway as POST /api/caverescue/<op>, authenticated with
their board token; the call is forwarded to the simulator on 127.0.0.1:7788 and logged on the
board so coordination metrics can see who did what.

    --ek board_plugins=build-mah/cr_board.py   (generated by ./build.sh; this file is its template)
"""
import asyncio
import json
import subprocess
import threading
import urllib.error
import urllib.request

from fastapi import Header, HTTPException, Request
from fastapi.responses import JSONResponse

SIM = "http://127.0.0.1:7788/api/"
LAUNCHER = "/usr/local/bin/caverescue-start"
# The scenario, photo library and seal key ship encrypted in the task image (every agent box is built from
# it, and agents run as root there). Only the hub gets this passphrase, through this plugin; ./build.sh
# writes it into the copy of this file it generates under build-mah/.
DATA_PASS = "__CR_DATA_PASS__"
DATA_ENC = "/opt/caverescue/data.enc"
OPS = {"briefing", "status", "map", "events", "photos", "photo", "fly", "explore", "wall", "charge", "load", "drop", "report", "rescue"}
_start_lock = threading.Lock()


def _unpack():
    """Decrypt the scenario data into the hub's root-only /opt/caverescue (once)."""
    import os
    if not os.path.exists(DATA_ENC) or os.path.isdir("/opt/caverescue/scenarios"): return
    env = dict(os.environ, CR_DATA_PASS=DATA_PASS)
    subprocess.run(f"openssl enc -d -aes-256-cbc -pbkdf2 -pass env:CR_DATA_PASS -in {DATA_ENC} | tar xzf - -C /opt/caverescue",
                   shell=True, check=True, env=env, timeout=600)


def _start():
    with _start_lock:
        _unpack()
        subprocess.run([LAUNCHER], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, timeout=600)


def _call(op, body):
    req = urllib.request.Request(SIM + op, data=body, headers={"Content-Type": "application/json"})
    try:
        with urllib.request.urlopen(req, timeout=600) as r:
            return r.status, r.read()
    except urllib.error.HTTPError as e:
        return e.code, e.read() or b"{}"
    except urllib.error.URLError:
        _start()
        with urllib.request.urlopen(req, timeout=600) as r:
            return r.status, r.read()


def register(board, api, mcp):
    threading.Thread(target=_start, daemon=True).start()  # loading the photo index takes a moment

    @api.post("/caverescue/{op}")
    async def caverescue(op: str, request: Request, authorization: str | None = Header(None)):
        token = authorization[7:].strip() if authorization and authorization.lower().startswith("bearer ") else None
        try:
            who = board.authenticate(token)
        except Exception as e:
            raise HTTPException(401, str(e)) from None
        if op not in OPS:
            raise HTTPException(404, f"unknown op {op}")
        code, out = await asyncio.to_thread(_call, op, await request.body())
        try:
            data = json.loads(out)
        except ValueError:
            data = {"error": out.decode(errors="replace")[:500]}
        board._emit("caverescue", who, op=op, status=code)
        return JSONResponse(data, status_code=code)
